function cylinder(name,x,y,z,r,h,color,room,axis='y',rz=r,extra={}){
 const lo=[],hi=[],n=16;
 for(let i=0;i<n;i++){const a=i/n*Math.PI*2,c=Math.cos(a),s=Math.sin(a);if(axis==='y'){lo.push([x+r*c,y,z+rz*s]);hi.push([x+r*c,y+h,z+rz*s]);}else if(axis==='x'){lo.push([x,y+r*c,z+rz*s]);hi.push([x+h,y+r*c,z+rz*s]);}else{lo.push([x+r*c,y+rz*s,z]);hi.push([x+r*c,y+rz*s,z+h]);}}
 for(let i=0;i<n;i++){let j=(i+1)%n,a=(i+.5)/n*Math.PI*2,c=Math.cos(a),s=Math.sin(a);const norm=axis==='y'?[c,0,s]:axis==='x'?[0,c,s]:[c,s,0];add([lo[i],lo[j],hi[j],hi[i]],norm,color,room,{name,...extra});}
 const nrm=axis==='y'?[0,1,0]:axis==='x'?[1,0,0]:[0,0,1];add(hi,nrm,color,room,{name,...extra});add(lo,nrm.map(v=>-v),color,room,{name,...extra});
}
function shadow(x,z,w,d,room){rect('',x-w/2-.035,z-d/2-.035,x+w/2+.055,z+d/2+.055,.031,palette.shadow,room,{alpha:.11});}
function piece(name,x,z,w,d,room,build,future=false){if(future&&!state.future)return;const previous=activeObjectId;activeObjectId=resolveObject(name,room);furniture.push({name,x,z,w,d,room,future,objectId:activeObjectId});shadow(x,z,w,d,room);build({future});activeObjectId=previous;}
