function tileGrid(poly,room,color){const xs=poly.map(p=>p[0]),zs=poly.map(p=>p[1]);const loX=Math.min(...xs),hiX=Math.max(...xs),loZ=Math.min(...zs),hiZ=Math.max(...zs);function hits(v,axis){const out=[];for(let i=0;i<poly.length;i++){let a=poly[i],b=poly[(i+1)%poly.length];if((a[axis]<=v&&b[axis]>v)||(b[axis]<=v&&a[axis]>v)){let t=(v-a[axis])/(b[axis]-a[axis]);out.push(a[1-axis]+t*(b[1-axis]-a[1-axis]));}}return out.sort((a,b)=>a-b);}
 const step=room==='bath'?.30:.60;
 for(let x=Math.ceil(loX/step)*step;x<hiX;x+=step){const h=hits(x,0);for(let i=0;i<h.length-1;i+=2)rect('',x-.003,h[i],x+.003,h[i+1],.023,color,room);}
 for(let z=Math.ceil(loZ/step)*step;z<hiZ;z+=step){const h=hits(z,1);for(let i=0;i<h.length-1;i+=2)rect('',h[i],z-.003,h[i+1],z+.003,.024,color,room);}
}
